#include <bits/stdc++.h>
using namespace std;

long long brute(const string&s,const string&t){
  int n=s.size(),m=t.size();
  long long ans=0;
  for(int i=0;i<n;i++){
    string A;
    for(int j=i;j<n;j++){
      A+=s[j]; int L=j-i+1;
      for(int k=1;k<=m && k<L;k++){
        string C=A+t.substr(0,k);
        string D=C; reverse(D.begin(),D.end());
        if(C==D) ans++;
      }
    }
  }
  return ans;
}

long long fast(const string&s,const string&t){
  int n=s.size(),m=t.size();
  if(n==0) return 0;
  vector<int> d1(n);
  for(int i=0,l=0,r=-1;i<n;i++){
    int k=(i>r)?1:min(d1[l+r-i], r-i+1);
    while(i-k>=0 && i+k<n && s[i-k]==s[i+k]) k++;
    d1[i]=k;
    if(i+k-1>r){ l=i-k+1; r=i+k-1; }
  }
  vector<int> d2(n);
  for(int i=0,l=0,r=-1;i<n;i++){
    int k=(i>r)?0:min(d2[l+r-i+1], r-i+1);
    while(i-k-1>=0 && i+k<n && s[i-k-1]==s[i+k]) k++;
    d2[i]=k;
    if(i+k-1>r){ l=i-k; r=i+k-1; }
  }
  vector<long long> diff(n+1,0);
  for(int i=0;i<n;i++){
    int lo=max(0,i-d1[i]+1), hi=i;
    diff[lo]++; diff[hi+1]--;
  }
  for(int i=0;i<n;i++) if(d2[i]>=1){
    int lo=max(0,i-d2[i]), hi=i-1;
    diff[lo]++; diff[hi+1]--;
  }
  vector<long long> A(n,0); long long run=0;
  for(int p=0;p<n;p++){ run+=diff[p]; A[p]=run; }
  string sr=s; reverse(sr.begin(),sr.end());
  vector<int> z(m,0); z[0]=m;
  for(int i=1,l=0,r=0;i<m;i++){
    if(i<=r) z[i]=min(r-i+1, z[i-l]);
    while(i+z[i]<m && t[z[i]]==t[i+z[i]]) z[i]++;
    if(i+z[i]-1>r){ l=i; r=i+z[i]-1; }
  }
  vector<int> ex(n,0);
  for(int i=0,l=0,r=-1;i<n;i++){
    if(i<=r) ex[i]=min(r-i+1, (i-l<m? z[i-l]:0));
    while(i+ex[i]<n && ex[i]<m && sr[i+ex[i]]==t[ex[i]]) ex[i]++;
    if(i+ex[i]-1>r){ l=i; r=i+ex[i]-1; }
  }
  long long ans=0;
  for(int p=1;p<n;p++) ans += A[p]*(long long)ex[n-p];
  return ans;
}

int main(){
  mt19937 rng(12345);
  for(int it=0; it<200000; it++){
    int n=2+rng()%8;
    int m=1+rng()%(n-1);
    string s,t;
    for(int i=0;i<n;i++) s+=char('a'+rng()%3);
    for(int i=0;i<m;i++) t+=char('a'+rng()%3);
    long long b=brute(s,t), f=fast(s,t);
    if(b!=f){
      printf("MISMATCH s=%s t=%s brute=%lld fast=%lld\n", s.c_str(), t.c_str(), b, f);
      return 0;
    }
  }
  printf("ALL OK\n");
  return 0;
}

